private E find(Node<E> node, E value) {
  if (node == null) {
    return null; // nicht gefunden
  } else if (node.getValue().compareTo(value) == 0) {
    return node.getValue(); // gefunden
  } else if (node.getValue().compareTo(value) > 0) {
    return find(node.getLeftBranch(), value); // links weiter
  } else {
    return find(node.getRightBranch(), value); // rechts weiter
  }
}

