public Circle createAnimatedSun(double radius) {
    Circle sun = new Circle(radius);
    sun.setFill(Color.OLDLACE);

    DropShadow sunShadow = new DropShadow();
    sunShadow.setColor(Color.DARKORANGE);
    sun.setEffect(sunShadow);

    ScaleTransition scaleAnimation =
        new ScaleTransition(Duration.millis(3000), sun);
    scaleAnimation.setCycleCount(Timeline.INDEFINITE);
    scaleAnimation.setAutoReverse(true);
    scaleAnimation.setByX(0.3);
    scaleAnimation.setByY(0.3);
    scaleAnimation.play();

    return sun;
}

