    private Knoten einfuegen(Knoten aktuell, Medium m) {
        if (aktuell == null) {
            return new Knoten(m);
        }
        if (m.getErscheinungsjahr() < aktuell.medium.getErscheinungsjahr()) {
            aktuell.links = einfuegen(aktuell.links, m);
        } else {
            aktuell.rechts = einfuegen(aktuell.rechts, m);
        }
        return aktuell;
    }

    public List<Medium> alsSortierteListe() {
        List<Medium> ergebnis = new ArrayList<Medium>();
        inorder(wurzel, ergebnis);
        return ergebnis;
    }

    private void inorder(Knoten aktuell, List<Medium> liste) {
        if (aktuell != null) {
            inorder(aktuell.links, liste);
            liste.add(aktuell.medium);
            inorder(aktuell.rechts, liste);
        }
    }
}
