import java.util.List;
import java.util.ArrayList;

public class MediumBaum {

    private Knoten wurzel;

    private class Knoten {
        Medium medium;
        Knoten links;
        Knoten rechts;

        Knoten(Medium medium) {
            this.medium = medium;
        }
    }

    public void einfuegen(Medium m) {
        wurzel = einfuegen(wurzel, m);
    }

    private Knoten einfuegen(Knoten aktuell, Medium m) {
        if (aktuell == null) {
            return new Knoten(m);
        }
        if (m.getErscheinungsjahr() < aktuell.medium.getErscheinungsjahr()) {
            aktuell.links = einfuegen(aktuell.links, m);
        } else {
            aktuell.rechts = einfuegen(aktuell.rechts, m);
        }
        return aktuell;
    }

    public boolean entfernen(int jahr) {
        boolean[] gefunden = new boolean[1];
        wurzel = entfernen(wurzel, jahr, gefunden);
        return gefunden[0];
    }

    private Knoten entfernen(Knoten aktuell, int jahr, boolean[] gefunden) {
        if (aktuell == null) {
