public class TaschenrechnerApp extends Application {

    private TextField zahl1Feld;
    private TextField zahl2Feld;
    private Label ergebnisLabel;

    @Override
    public void start(Stage primaryStage) {
        zahl1Feld = new TextField();
        zahl2Feld = new TextField();
        ergebnisLabel = new Label("Ergebnis: -");

        Button plusButton = new Button("+");
        Button minusButton = new Button("-");
        Button malButton = new Button("*");
        Button geteiltButton = new Button("/");

        plusButton.setOnAction(new EventHandler<ActionEvent>() {
            @Override
            public void handle(ActionEvent event) {
                berechne("+");
            }
        });

        minusButton.setOnAction(event -> berechne("-"));
        malButton.setOnAction(event -> berechne("*"));
        geteiltButton.setOnAction(event -> berechne("/"));

        GridPane container1 = new GridPane();
        container1.add(zahl1Feld, 0, 0);
        container1.add(zahl2Feld, 1, 0);
        container1.add(plusButton, 0, 1);
        container1.add(minusButton, 1, 1);
        container1.add(malButton, 0, 2);
        container1.add(geteiltButton, 1, 2);
        container1.add(ergebnisLabel, 0, 3, 2, 1);

        Scene scene1 = new Scene(container1, 300, 200);

        primaryStage.setTitle("Taschenrechner");
        primaryStage.setScene(scene1);
        primaryStage.show();
    }

    private void berechne(String operator) {
        try {
            double zahl1 = Double.parseDouble(zahl1Feld.getText());
            double zahl2 = Double.parseDouble(zahl2Feld.getText());
            double ergebnis;

            switch (operator) {
                case "+":
                    ergebnis = zahl1 + zahl2;
                    break;
                case "-":
                    ergebnis = zahl1 - zahl2;
                    break;
                case "*":
                    ergebnis = zahl1 * zahl2;
                    break;
                case "/":
                    if (zahl2 == 0) {
                        ergebnisLabel.setText("Fehler: Division durch 0");
                        return;
                    }
                    ergebnis = zahl1 / zahl2;
                    break;
                default:
                    ergebnisLabel.setText("Fehler: Unbekannter Operator");
                    return;
            }

            ergebnisLabel.setText("Ergebnis: " + ergebnis);
        } catch (NumberFormatException e) {
            ergebnisLabel.setText("Fehler: Ungültige Eingabe");
        }
    }

    public static void main(String[] args) {
        launch(args);
    }
}
