    private double y;

    public Punkt() {
        this(0.0, 0.0);
    }

    public Punkt(double x, double y) {
        this.x = x;
        this.y = y;
    }

    public Punkt(Punkt vorlage) {
        this(vorlage.x, vorlage.y);
    }

    public double getX() {
        return x;
    }

    public double getY() {
        return y;
    }

    public void setX(double x) {
        this.x = x;
    }

    public void setY(double y) {
        this.y = y;
    }
}

public class Linie {
    private Punkt start;
    private Punkt ende;

    public Linie() {
        this(new Punkt(0.0, 0.0), new Punkt(1.0, 1.0));
    }

    public Linie(Punkt start, Punkt ende) {
        this.start = new Punkt(start);
        this.ende = new Punkt(ende);
    }

    public Linie(Linie vorlage) {
        this(vorlage.start, vorlage.ende);
    }

    public Punkt getStart() {
        return new Punkt(start);
    }

    public Punkt getEnde() {
        return new Punkt(ende);
    }

    public double getLaenge() {
        double dx = ende.getX() - start.getX();
        double dy = ende.getY() - start.getY();
        return Math.sqrt(dx * dx + dy * dy);
    }

