import javafx.scene.paint.Color;
import javafx.scene.shape.Polygon;
import javafx.scene.shape.Rectangle;
import javafx.scene.transform.Translate;

public class Haeuserreihe {

    private static final double WAND_BREITE = 60;
    private static final double WAND_HOEHE = 50;
    private static final double ABSTAND = 20;
    private static final double START_X = 20;
    private static final double START_Y = 150;

    public void zeichneHaeuserreihe(Pane pane, int anzahl, Color[] fassadenfarben) {
        if (anzahl <= 0) {
            throw new IllegalArgumentException("anzahl muss groesser als 0 sein");
        }
        if (fassadenfarben == null || fassadenfarben.length != anzahl) {
            throw new IllegalArgumentException("fassadenfarben muss genau 'anzahl' Farben enthalten");
        }

        for (int i = 0; i < anzahl; i++) {
            Group haus = erzeugeHaus(fassadenfarben[i]);
            double dx = START_X + i * (WAND_BREITE + ABSTAND);
            haus.getTransforms().add(new Translate(dx, START_Y));
            pane.getChildren().add(haus);
        }
    }

    private Group erzeugeHaus(Color fassadenfarbe) {
        Rectangle wand = new Rectangle(0, 0, WAND_BREITE, WAND_HOEHE);
        wand.setFill(fassadenfarbe);
        wand.setStroke(Color.BLACK);

        Polygon dach = new Polygon(
                0.0, 0.0,
                WAND_BREITE / 2.0, -30.0,
                WAND_BREITE, 0.0
        );
        dach.setFill(Color.DARKRED);
        dach.setStroke(Color.BLACK);

        Group haus = new Group();
        haus.getChildren().addAll(wand, dach);
        return haus;
    }
}
