import javafx.scene.canvas.GraphicsContext;
import javafx.scene.paint.Color;

public class Balkendiagramm {

    private static final double BASELINE = 150;
    private static final double BAR_WIDTH = 30;
    private static final double GAP = 10;
    private static final double START_X = 20;

    public void zeichneBalkendiagramm(GraphicsContext gc, int[] werte) {
        gc.setStroke(Color.BLACK);
        gc.setLineWidth(1);
        double breite = START_X + werte.length * (BAR_WIDTH + GAP);
        gc.strokeLine(0, BASELINE, breite, BASELINE);

        if (werte.length == 0) {
            return; // Edge Case: leeres Array -> nur Nulllinie
        }

        int maxIndex = indexDesGroesstenBetrags(werte);

        for (int i = 0; i < werte.length; i++) {
            int wert = werte[i];
            if (wert == 0) {
                continue; // Edge Case: kein Balken bei Wert 0
            }

            double x = START_X + i * (BAR_WIDTH + GAP);
            double y;
            double hoehe;

            if (wert > 0) {
                gc.setFill(Color.LIMEGREEN);
                y = BASELINE - wert;
                hoehe = wert;
            } else {
                gc.setFill(Color.CRIMSON);
                y = BASELINE;
                hoehe = -wert;
            }

            gc.fillRect(x, y, BAR_WIDTH, hoehe);

            if (i == maxIndex) {
                gc.setStroke(Color.BLACK);
                gc.setLineWidth(2);
                gc.strokeRect(x, y, BAR_WIDTH, hoehe);
            }
        }
    }

    private int indexDesGroesstenBetrags(int[] werte) {
        int maxIndex = 0;
        for (int i = 1; i < werte.length; i++) {
            if (Math.abs(werte[i]) > Math.abs(werte[maxIndex])) {
                maxIndex = i;
            }
        }
        return maxIndex;
    }
}
