import java.util.ArrayList;
import java.util.List;

public interface Beobachter {
    void aktualisiere(double temperatur);

    default String bezeichnung() {
        return "Beobachter";
    }
}

class Temperatursensor {
    private List<Beobachter> beobachterListe = new ArrayList<>();
    private double temperatur;

    public void anmelden(Beobachter b) {
        if (!beobachterListe.contains(b)) {
            beobachterListe.add(b);
        }
    }

    public void abmelden(Beobachter b) {
        beobachterListe.remove(b);
    }

    public void setTemperatur(double neueTemperatur) {
        this.temperatur = neueTemperatur;
        for (Beobachter b : beobachterListe) {
            b.aktualisiere(neueTemperatur);
        }
    }
}

class KonsolenAnzeige implements Beobachter {
    @Override
    public void aktualisiere(double temperatur) {
        System.out.println(bezeichnung() + ": aktuelle Temperatur = " + temperatur + " Grad");
    }
}

class AlarmAnzeige implements Beobachter {
    private double schwellwert;

    public AlarmAnzeige(double schwellwert) {
        this.schwellwert = schwellwert;
    }

    @Override
    public void aktualisiere(double temperatur) {
        if (temperatur > schwellwert) {
            System.out.println("ALARM (" + bezeichnung() + "): Temperatur " + temperatur + " Grad ueberschreitet Schwellwert " + schwellwert + " Grad!");
        }
    }

    @Override
    public String bezeichnung() {
        return "Alarmanzeige";
    }
}

public class Ueberwachung {
    public static void main(String[] args) {
        Temperatursensor sensor = new Temperatursensor();
        KonsolenAnzeige konsole = new KonsolenAnzeige();
        AlarmAnzeige alarm25 = new AlarmAnzeige(25.0);
        AlarmAnzeige alarm30 = new AlarmAnzeige(30.0);

        sensor.anmelden(konsole);
        sensor.anmelden(alarm25);
        sensor.anmelden(alarm30);
        sensor.anmelden(konsole); // wird ignoriert, da bereits angemeldet

        sensor.setTemperatur(20.0);
        sensor.setTemperatur(27.0);
        sensor.setTemperatur(35.0);

        sensor.abmelden(alarm25);
        sensor.setTemperatur(40.0); // alarm25 reagiert nicht mehr, alarm30 schon
    }
}
