            beobachterListe.add(b);
        }
    }

    public void abmelden(Beobachter b) {
        beobachterListe.remove(b);
    }

    public void setTemperatur(double neueTemperatur) {
        this.temperatur = neueTemperatur;
        for (Beobachter b : beobachterListe) {
            b.aktualisiere(neueTemperatur);
        }
    }
}

class KonsolenAnzeige implements Beobachter {
