import java.util.ArrayList;
import java.util.List;
import java.util.NoSuchElementException;

public class Statistik<E extends Number & Comparable<E>> {

    private final List<E> werte = new ArrayList<>();

    public void add(E wert) {
        werte.add(wert);
    }

    public E max() {
        if (werte.isEmpty()) {
            throw new NoSuchElementException("Statistik ist leer");
        }
        E maximum = werte.get(0);
        for (E wert : werte) {
            if (wert.compareTo(maximum) > 0) {
                maximum = wert;
            }
        }
        return maximum;
    }

    public double summe() {
        double summe = 0;
        for (E wert : werte) {
            summe += wert.doubleValue();
        }
        return summe;
    }

    public static double summeAlle(List<? extends Number> liste) {
        double summe = 0;
        for (Number n : liste) {
            summe += n.doubleValue();
        }
        return summe;
    }
}
