import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.NoSuchElementException;

public class SortierteListe<E extends Comparable<E>> {

    private final List<E> elemente = new ArrayList<>();

    public void einfuegen(E element) {
        int index = 0;
        while (index < elemente.size() && elemente.get(index).compareTo(element) <= 0) {
            index++;
        }
        elemente.add(index, element);
    }

    public E kleinstes() {
        if (elemente.isEmpty()) {
            throw new NoSuchElementException("Liste ist leer");
        }
        return elemente.get(0);
    }

    public E groesstes() {
        if (elemente.isEmpty()) {
            throw new NoSuchElementException("Liste ist leer");
        }
        return elemente.get(elemente.size() - 1);
    }

    public void sortiereMit(Comparator<? super E> comparator) {
        elemente.sort(comparator);
    }

    public List<E> alsListe() {
        return new ArrayList<>(elemente);
    }

    public static <T> void kopiere(List<? super T> ziel, List<? extends T> quelle) {
        for (T element : quelle) {
            ziel.add(element);
        }
    }

    public static class Paar<A, B> {
        private final A erster;
        private final B zweiter;

        public Paar(A erster, B zweiter) {
            this.erster = erster;
            this.zweiter = zweiter;
        }

        public A getErster() {
            return erster;
        }

        public B getZweiter() {
            return zweiter;
        }
    }

    public static <A extends Comparable<A>, B> Paar<A, B> maxNachErstem(List<Paar<A, B>> liste) {
        if (liste.isEmpty()) {
            throw new NoSuchElementException("Liste ist leer");
        }
        Paar<A, B> maximum = liste.get(0);
        for (Paar<A, B> paar : liste) {
            if (paar.getErster().compareTo(maximum.getErster()) > 0) {
                maximum = paar;
            }
        }
        return maximum;
    }
}
