public class LinkedListInt {
    private ElementInt head;
    private ElementInt tail;

    public void addLast(int value) {
        ElementInt elementInt = new ElementInt(value);
        if (head == null) {
            head = elementInt;
            tail = head;
        } else {
            tail.setNext(elementInt);
            tail = elementInt;
        }
    }

    public void reverse() {
        tail = head;
        ElementInt previous = null;
        ElementInt current = head;
        while (current != null) {
            ElementInt nextNode = current.getNext();
            current.setNext(previous);
            previous = current;
            current = nextNode;
        }
        head = previous;
    }

    @Override
    public String toString() {
        StringBuilder listString = new StringBuilder();
        listString.append("(");
        ElementInt currentElement = head;
        while (currentElement != null) {
            listString.append(currentElement);
            currentElement = currentElement.getNext();
            if (currentElement != null) {
                listString.append(" ");
            }
        }
        listString.append(")");
        return listString.toString();
    }

    public static void main(String[] args) {
        LinkedListInt list = new LinkedListInt();
        list.addLast(1);
        list.addLast(2);
        list.addLast(3);
        list.addLast(4);
        System.out.println(list);
        list.reverse();
