import java.util.*;

class Account implements Comparable<Account> {
    String owner;
    double balance;

    Account(String owner, double balance) {
        this.owner = owner;
        this.balance = balance;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        Account a = (Account) o;
        return owner.equals(a.owner);
    }

    @Override
    public int hashCode() {
        return Objects.hash(owner);
    }

    @Override
    public int compareTo(Account other) {
        return Double.compare(other.balance, this.balance);
    }

    static List<Account> aggregateAndSort(List<Account> transactions) {
        Map<String, Double> sums = new HashMap<>();
        for (Account t : transactions) {
            sums.merge(t.owner, t.balance, Double::sum);
        }
        List<Account> result = new ArrayList<>();
        for (Map.Entry<String, Double> e : sums.entrySet()) {
            result.add(new Account(e.getKey(), e.getValue()));
        }
        Collections.sort(result);
        return result;
    }

    public static void main(String[] args) {
        List<Account> transactions = Arrays.asList(
            new Account("Anna", 100.0),
            new Account("Bob", 50.0),
            new Account("Anna", 30.0),
            new Account("Chris", 200.0)
        );
        List<Account> result = aggregateAndSort(transactions);
        for (Account a : result) {
            System.out.println(a.owner + ": " + a.balance);
        }
    }
}
