class EventBox<E> implements Iterable<E> {
    private final E[] items;
    private int size = 0;

    @SuppressWarnings("unchecked")
    EventBox(int capacity) {
        items = (E[]) new Object[capacity];
    }

    boolean add(E element) {
        if (size >= items.length) return false;
        items[size] = element;
        size++;
        return true;
    }

    @Override
    public Iterator<E> iterator() {
        return new Iterator<E>() {
            private int index = 0;

            @Override
            public boolean hasNext() {
                return index < size;
            }

            @Override
            public E next() {
                if (!hasNext()) throw new NoSuchElementException();
                E element = items[index];
                index++;
                return element;
            }
        };
    }
}

class EventPlanner {

    static Map<String, List<Event>> planByRoom(List<Event> events) {
        Map<String, List<Event>> plan = new HashMap<>();
        Set<Event> seen = new HashSet<>();
        for (Event e : events) {
            if (!seen.add(e)) continue;
            plan.computeIfAbsent(e.room, k -> new ArrayList<>()).add(e);
        }
        for (List<Event> roomEvents : plan.values()) {
            Collections.sort(roomEvents);
        }
        return plan;
    }

    static List<String> roomsSortedByEventCount(Map<String, List<Event>> plan) {
