public class BinaryTree<E extends Comparable<E>> {
    private Node<E> root;

    public void insert(E value) {
        root = insert(root, value);
    }

    private Node<E> insert(Node<E> node, E value) {
        if (node == null) {
            return new Node<>(value);
        } else if (node.getValue().compareTo(value) > 0) {
            node.setLeftBranch(insert(node.getLeftBranch(), value));
        } else if (node.getValue().compareTo(value) < 0) {
            node.setRightBranch(insert(node.getRightBranch(), value));
        }
        // bei compareTo == 0: Duplikat, node bleibt unveraendert
        return node;
    }

    public void inorder(Node<E> node, StringBuilder sb) {
        if (node != null) {
            inorder(node.getLeftBranch(), sb);
            sb.append(node.getValue()).append(" ");
            inorder(node.getRightBranch(), sb);
        }
    }

    static class Node<E> {
        private E value;
        private Node<E> left;
        private Node<E> right;

        Node(E value) { this.value = value; }
        E getValue() { return value; }
        void setValue(E value) { this.value = value; }
        Node<E> getLeftBranch() { return left; }
        void setLeftBranch(Node<E> left) { this.left = left; }
        Node<E> getRightBranch() { return right; }
        void setRightBranch(Node<E> right) { this.right = right; }
    }

