            node.setLeftBranch(insert(node.getLeftBranch(), value));
        } else if (node.getValue().compareTo(value) < 0) {
            node.setRightBranch(insert(node.getRightBranch(), value));
        }
        return node;
    }

    public int height() {
        return height(root);
    }

    private int height(Node<E> node) {
        if (node == null) {
            return -1;
        }
        return 1 + Math.max(height(node.getLeftBranch()), height(node.getRightBranch()));
    }

    public int countLeaves() {
        return countLeaves(root);
    }

    private int countLeaves(Node<E> node) {
        if (node == null) {
            return 0;
        }
        if (node.getLeftBranch() == null && node.getRightBranch() == null) {
            return 1;
        }
        return countLeaves(node.getLeftBranch()) + countLeaves(node.getRightBranch());
    }

    public boolean isBalanced() {
        return checkBalanced(root) != UNBALANCED;
    }

    private int checkBalanced(Node<E> node) {
        if (node == null) {
            return -1;
        }
        int leftHeight = checkBalanced(node.getLeftBranch());
        if (leftHeight == UNBALANCED) {
            return UNBALANCED;
        }
        int rightHeight = checkBalanced(node.getRightBranch());
        if (rightHeight == UNBALANCED) {
            return UNBALANCED;
        }
        if (Math.abs(leftHeight - rightHeight) > 1) {
            return UNBALANCED;
        }
        return 1 + Math.max(leftHeight, rightHeight);
    }

    static class Node<E> {
        private E value;
        private Node<E> left;
        private Node<E> right;

        Node(E value) { this.value = value; }
        E getValue() { return value; }
        void setValue(E value) { this.value = value; }
        Node<E> getLeftBranch() { return left; }
        void setLeftBranch(Node<E> left) { this.left = left; }
        Node<E> getRightBranch() { return right; }
        void setRightBranch(Node<E> right) { this.right = right; }
    }

    public static void main(String[] args) {
        BinaryTree<Integer> baum = new BinaryTree<>();
        int[] werte = {50, 30, 70, 20, 40, 60, 80};
        for (int w : werte) {
            baum.insert(w);
        }
        System.out.println("Hoehe: " + baum.height());          // 2
        System.out.println("Blaetter: " + baum.countLeaves());  // 4
        System.out.println("Balanciert: " + baum.isBalanced()); // true

        baum.insert(10);
        baum.insert(5);
        System.out.println("Balanciert nach 10,5: " + baum.isBalanced()); // false
    }
}
