import javafx.stage.Stage;

public class RectangleApp extends Application {

    public static class RectangleModel {
        private float width = 1;
        private float height = 1;

        public boolean setWidth(String widthString) {
            float value;
            try {
                value = Float.parseFloat(widthString);
            } catch (NumberFormatException numberFormatException) {
                return false;
            }
            if (value <= 0) {
                return false;
            }
            width = value;
            return true;
        }

        public boolean setHeight(String heightString) {
            float value;
            try {
                value = Float.parseFloat(heightString);
            } catch (NumberFormatException numberFormatException) {
                return false;
            }
            if (value <= 0) {
                return false;
            }
            height = value;
            return true;
        }

        public float getWidth() { return width; }
        public float getHeight() { return height; }
        public float area() { return width * height; }
        public float perimeter() { return 2 * (width + height); }
    }

