        Button resetButton = new Button("Zur\u00fccksetzen");

        widthInputField.focusedProperty().addListener((observable, wasFocused, isNowFocused) -> {
            if (!isNowFocused) {
                String oldWidthText = String.valueOf(rectangleModel.getWidth());
                if (rectangleModel.setWidth(widthInputField.getText())) {
                    resultLabel.setText("Fl\u00e4che: " + rectangleModel.area()
                        + " cm^2, Umfang: " + rectangleModel.perimeter() + " cm");
                } else {
                    widthInputField.setText(oldWidthText);
                }
            }
        });

        heightInputField.focusedProperty().addListener((observable, wasFocused, isNowFocused) -> {
            if (!isNowFocused) {
                String oldHeightText = String.valueOf(rectangleModel.getHeight());
                if (rectangleModel.setHeight(heightInputField.getText())) {
                    resultLabel.setText("Fl\u00e4che: " + rectangleModel.area()
                        + " cm^2, Umfang: " + rectangleModel.perimeter() + " cm");
                } else {
                    heightInputField.setText(oldHeightText);
                }
            }
        });

        resetButton.setOnAction(event -> {
            rectangleModel.setWidth("1");
            rectangleModel.setHeight("1");
            widthInputField.setText("<Breite in cm>");
            heightInputField.setText("<H\u00f6he in cm>");
            resultLabel.setText("");
        });

        VBox vBox = new VBox();
        vBox.setPadding(new Insets(10, 10, 10, 10));
        vBox.setSpacing(8);
        vBox.getChildren().add(widthLayoutLine);
        vBox.getChildren().add(heightLayoutLine);
        vBox.getChildren().add(resultLabel);
        vBox.getChildren().add(resetButton);

        primaryStage.setScene(new Scene(vBox, 320, 220));
        primaryStage.setTitle("Rechteck-Rechner");
        primaryStage.show();
    }

    public static void main(String[] args) {
        launch(args);
    }
}

