package app;

import javafx.event.ActionEvent;
import javafx.fxml.FXML;
import javafx.fxml.Initializable;
import javafx.scene.control.Label;
import javafx.scene.control.TextField;

import java.net.URL;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.ResourceBundle;

class Punktekonto {
    private int summe = 0;

    public void addPunkte(int punkte) {
        summe += punkte;
    }

    public int getSumme() {
        return summe;
    }
}

public class PunkteController implements Initializable {

    @FXML
    private Label anzeigeLabel;

    @FXML
    private Label statusLabel;

    @FXML
    private TextField eingabeField;

    private Punktekonto konto;

    private final Deque<Integer> verlauf = new ArrayDeque<>();

    public void setModel(Punktekonto konto) {
        this.konto = konto;
        updateAnzeige();
    }

    @Override
    public void initialize(URL location, ResourceBundle resources) {
        eingabeField.focusedProperty().addListener((obs, wasFocused, isNowFocused) -> {
            if (!isNowFocused && !eingabeField.getText().isEmpty()) {
                try {
                    Integer.parseInt(eingabeField.getText());
                    statusLabel.setText("");
                } catch (NumberFormatException e) {
                    statusLabel.setText("Ungültige Zahl!");
                }
            }
        });
    }

    @FXML
    private void handleAdd(ActionEvent event) {
        try {
            int punkte = Integer.parseInt(eingabeField.getText());
            konto.addPunkte(punkte);
            verlauf.push(punkte);
            statusLabel.setText("");
            updateAnzeige();
        } catch (NumberFormatException e) {
            statusLabel.setText("Ungültige Zahl!");
        } finally {
            eingabeField.setText("");
        }
    }

    @FXML
    private void handleUndo(ActionEvent event) {
        if (verlauf.isEmpty()) {
            statusLabel.setText("Nichts rückgängig zu machen!");
            return;
        }
        int letzte = verlauf.pop();
        konto.addPunkte(-letzte);
        statusLabel.setText("");
        updateAnzeige();
    }

    private void updateAnzeige() {
        anzeigeLabel.setText(String.valueOf(konto.getSumme()));
    }
}
