private Canvas canvas;
private List<double[]> points = new ArrayList<>();

public void handleCanvasClicked(MouseEvent event) {
    points.add(new double[] { event.getX(), event.getY() });
    redraw();
}

public void redraw() {
    GraphicsContext g = canvas.getGraphicsContext2D();
    g.clearRect(0, 0, canvas.getWidth(), canvas.getHeight());

    for (double[] point : points) {
        double x = point[0];
        double y = point[1];
        g.setFill(Color.DODGERBLUE);
        g.fillOval(x - 8, y - 8, 16, 16);
    }

    if (!points.isEmpty()) {
        double[] lastPoint = points.get(points.size() - 1);
        double x = lastPoint[0];
        double y = lastPoint[1];
        g.setFill(Color.RED);
        g.fillOval(x - 16, y - 16, 32, 32);
    }
}
