}

public class TierTest {
    public static void main(String[] args) {
        Giraffe g = new Giraffe();
        g.fresse(); g.atmeMitLunge(); g.saeugeJunge(); g.gibLaut(); g.laufe(); g.frissBlaetter();
        Wal w = new Wal();
